-- Local synthetic rollback only. No connected identities or Storage API calls.
begin;
create temp table domain_results(name text primary key);grant select,insert on domain_results to anon,authenticated,service_role;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED %',label;end if;insert into pg_temp.domain_results values(label);end$$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$declare caught text;msg text;begin begin execute sql;exception when others then get stacked diagnostics caught=returned_sqlstate,msg=message_text;end;if caught is distinct from code then raise exception 'FAILED % expected % got % (%)',label,code,caught,msg;end if;insert into pg_temp.domain_results values(label);end$$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)::void$$;
create function pg_temp.config(title text default 'Approved teacher site') returns jsonb language sql as $$select jsonb_build_object('displayName','Fictional academy','heroTitle',title,'heroSubtitle','Learn safely','about','Approved public copy','locale','en','theme','green','accent','green','ctaLabel','Request access','ctaTarget','sign-up','sections',jsonb_build_array('hero','about','programs','courses'),'logoAssetId',null,'heroAssetId',null)$$;
create function pg_temp.cmd(action text,data jsonb default '{}',revision bigint default null,org uuid default '20000000-0000-0000-0000-000000000001') returns jsonb language sql as $$select public.teacher_website_command(action,org,coalesce(revision,(select revision from public.organization_websites where organization_id=org),0),data)$$;
create function pg_temp.site() returns uuid language sql as $$select current_setting('m6d.site')::uuid$$;
-- Extra domain lifecycle and trusted-operator regressions; entire suite rolls back.
set local role authenticated;select pg_temp.claim(1);
select set_config('m6d.site',pg_temp.cmd('create',jsonb_build_object('slug','domain-fixture','config',pg_temp.config()))->'website'->>'id',true);
select set_config('m6d.domain',pg_temp.cmd('domain.claim','{"hostname":"domain-fixture.org"}')->'domain'->>'id',true);
select set_config('m6d.proof',(select challenge from public.organization_website_domains where id=current_setting('m6d.domain')::uuid),true);
select pg_temp.ok(public.resolve_teacher_website('domain-fixture.org') is null,'pending domain cannot resolve');
select pg_temp.denied($q$select public.review_website_resource('domain',current_setting('m6d.domain')::uuid,0,true,'forged-by-owner','{}')$q$,'42501','owner cannot approve DNS or HTTPS');
select pg_temp.claim(2);select pg_temp.denied($q$select pg_temp.cmd('domain.claim','{"hostname":"teacher-forgery.org"}')$q$,'42501','ordinary teacher cannot claim domain');
select pg_temp.claim(4);select pg_temp.denied($q$select pg_temp.cmd('domain.rotate',jsonb_build_object('id',current_setting('m6d.domain'),'revision',0))$q$,'42501','assistant cannot rotate proof');
select pg_temp.claim(5);select pg_temp.denied($q$select pg_temp.cmd('domain.disable',jsonb_build_object('id',current_setting('m6d.domain'),'revision',0))$q$,'42501','student cannot disable another site');
reset role;
update public.organization_memberships set role='admin' where organization_id='20000000-0000-0000-0000-000000000001' and user_id='10000000-0000-0000-0000-000000000004';
set local role authenticated;select pg_temp.claim(4);
select pg_temp.cmd('domain.rotate',jsonb_build_object('id',current_setting('m6d.domain'),'revision',0));
select pg_temp.ok((select challenge<>current_setting('m6d.proof') and revision=1 from public.organization_website_domains where id=current_setting('m6d.domain')::uuid),'admin rotation changes token and revision');
select pg_temp.denied($q$select pg_temp.cmd('domain.disable',jsonb_build_object('id',current_setting('m6d.domain'),'revision',0))$q$,'PT409','stale binding revision rejected independently of fresh site revision');
reset role;set local role service_role;
select pg_temp.denied($q$select public.review_website_resource('domain',current_setting('m6d.domain')::uuid,1,true,'rotated-old-proof',jsonb_build_object('challenge',current_setting('m6d.proof'),'certificateReady',true))$q$,'42501','rotated proof with fresh revision still rejected');
reset role;
select set_config('m6d.proof',(select challenge from public.organization_website_domains where id=current_setting('m6d.domain')::uuid),true);
update public.organization_website_domains set challenge_expires_at=now()-interval '1 second' where id=current_setting('m6d.domain')::uuid;
set local role service_role;
select pg_temp.denied($q$select public.review_website_resource('domain',current_setting('m6d.domain')::uuid,1,true,'expired-dns-proof',jsonb_build_object('challenge',current_setting('m6d.proof'),'certificateReady',true))$q$,'42501','expired exact proof rejected');
reset role;update public.organization_website_domains set challenge_expires_at=now()+interval '1 hour' where id=current_setting('m6d.domain')::uuid;
set local role service_role;
select public.review_website_resource('domain',current_setting('m6d.domain')::uuid,1,true,'mock-DNS-no-HTTPS',jsonb_build_object('challenge',current_setting('m6d.proof'),'certificateReady',false));
reset role;set local role authenticated;select pg_temp.claim(1);
select pg_temp.ok(public.resolve_teacher_website('domain-fixture.org') is null,'verified without HTTPS cannot route');
select pg_temp.denied($q$select pg_temp.cmd('domain.activate',jsonb_build_object('id',current_setting('m6d.domain'),'revision',2))$q$,'42501','DNS is not certificate eligibility');
reset role;set local role service_role;
select public.review_website_resource('domain',current_setting('m6d.domain')::uuid,2,true,'mock-HTTPS-review',jsonb_build_object('challenge',current_setting('m6d.proof'),'certificateReady',true));
reset role;set local role authenticated;select pg_temp.claim(1);
select pg_temp.cmd('domain.activate',jsonb_build_object('id',current_setting('m6d.domain'),'revision',3));
select pg_temp.ok(public.resolve_teacher_website('domain-fixture.org') is null,'active domain cannot expose draft website');
select pg_temp.cmd('publish');
set local role anon;
select pg_temp.ok(public.resolve_teacher_website('domain-fixture.org')->>'slug'='domain-fixture','active eligible published domain resolves allowlisted slug');
select pg_temp.ok((select array_agg(k order by k)=array['slug','version'] from jsonb_object_keys(public.resolve_teacher_website('domain-fixture.org')) k),'anonymous binding has only slug and publication version');
select pg_temp.denied('select challenge from public.organization_website_domains','42501','anonymous cannot retrieve proofs');
select pg_temp.denied($q$select public.review_website_resource('domain',current_setting('m6d.domain')::uuid,4,true,'forged-anonymous','{}')$q$,'42501','anonymous cannot invoke review');
reset role;update public.organizations set status='suspended' where id='20000000-0000-0000-0000-000000000001';
set local role anon;select pg_temp.ok(public.resolve_teacher_website('domain-fixture.org') is null,'suspended organization stops anonymous routing');
reset role;update public.organizations set status='active' where id='20000000-0000-0000-0000-000000000001';
set local role service_role;
select public.review_website_resource('domain',current_setting('m6d.domain')::uuid,4,true,'mock-revalidation',jsonb_build_object('challenge',current_setting('m6d.proof'),'certificateReady',false));
reset role;
select pg_temp.ok((select state='verified' and not certificate_ready from public.organization_website_domains where id=current_setting('m6d.domain')::uuid),'revalidation deliberately removes active state and HTTPS eligibility');
set local role anon;select pg_temp.ok(public.resolve_teacher_website('domain-fixture.org') is null,'revalidation cannot silently retain routing');
reset role;set local role authenticated;select pg_temp.claim(1);
select pg_temp.cmd('domain.disable',jsonb_build_object('id',current_setting('m6d.domain'),'revision',5));
select pg_temp.ok((select state='disabled' and revision=6 from public.organization_website_domains where id=current_setting('m6d.domain')::uuid),'disable retains audited binding');
select pg_temp.claim(3);
select pg_temp.cmd('create',jsonb_build_object('slug','other-domain-fixture','config',pg_temp.config()),0,'20000000-0000-0000-0000-000000000002');
select pg_temp.denied($q$select pg_temp.cmd('domain.claim','{"hostname":"domain-fixture.org"}',null,'20000000-0000-0000-0000-000000000002')$q$,'23505','disabled claims cannot be taken over by another tenant');
select pg_temp.denied($q$select pg_temp.cmd('domain.rotate',jsonb_build_object('id',current_setting('m6d.domain'),'revision',6),null,'20000000-0000-0000-0000-000000000002')$q$,'42501','domain id cannot cross website scope');
reset role;
select pg_temp.ok(not has_function_privilege('authenticated','public.create_organization(text,text)','execute'),'manual organization provisioning restriction retained');
select count(*)::int domain_tests from pg_temp.domain_results;
rollback;
